import ctypes

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)

    def allocate(self, rows, cols):
        self.matrix = gsl.gsl_matrix_alloc(rows, cols)
        return self

    def free(self):
        gsl.gsl_matrix_free(self.matrix)

    def to_numpy(self):
        data = gsl.gsl_matrix_get_data(self.matrix)
        rows = gsl.gsl_matrix_get_rows(self.matrix)
        cols = gsl.gsl_matrix_get_cols(self.matrix)
        return np.ctypeslib.as_array(data, shape=(rows, cols))

def numpy_to_gsl_matrix(np_array):
    if len(np_array.shape) != 2:
        raise ValueError("Input must be a 2D array")
    data = np_array.ctypes.data_as(ctypes.c_void_p)
    rows = np_array.shape[0]
    cols = np_array.shape[1]
    matrix = gsl.gsl_matrix_alloc(rows, cols)
    gsl.gsl_matrix_set_data(matrix, data)
    return GSLMatrix(matrix)

def gsl_matrix_to_numpy(matrix):
    data = gsl.gsl_matrix_get_data(matrix.matrix)
    rows = gsl.gsl_matrix_get_rows(matrix.matrix)
    cols = gsl.gsl_matrix_get_cols(matrix.matrix)
    return np.ctypeslib.as_array(data, shape=(rows, cols))

