def compute_covariance(jacobian, epsrel, cov_dim):
    if len(jacobian.shape) != 2:
        raise ValueError("Jacobian must be a 2D array")
    if cov_dim <= 0:
        raise ValueError("Covariance dimension must be positive")
    if jacobian.shape[1] != cov_dim:
        raise ValueError("Jacobian column count must match covariance dimension")

