def fit_bspline(x, y, weights=None):
    if len(x) != len(y):
        raise ValueError("x and y must have the same length")
    if weights is not None and len(weights) != len(y):
        raise ValueError("weights must have the same length as y")
    n = len(x)
    x_vec = gsl.gsl_vector_alloc(n)
    for i in range(n):
        gsl.gsl_vector_set(x_vec, i, x[i])
    y_vec = gsl.gsl_vector_alloc(n)
    for i in range(n):
        gsl.gsl_vector_set(y_vec, i, y[i])
    weights_vec = None
    if weights is not None:
        weights_vec = gsl.gsl_vector_alloc(n)
        for i in range(n):
            gsl.gsl_vector_set(weights_vec, i, weights[i])
    workspace = gsl.gsl_bspline_workspace_alloc(n)
    coeffs = gsl.gsl_vector_alloc(n)
    gsl.gsl_bspline_wlssolve(x_vec, y_vec, weights_vec, coeffs, workspace)
    chi_squared = gsl.gsl_bspline_workspace_chisq(workspace)
    coefficients = [gsl.gsl_vector_get(coeffs, i) for i in range(n)]
    gsl.gsl_vector_free(x_vec)
    gsl.gsl_vector_free(y_vec)
    if weights_vec is not None:
        gsl.gsl_vector_free(weights_vec)
    gsl.gsl_vector_free(coeffs)
    gsl.gsl_bspline_workspace_free(workspace)
    return (coefficients, chi_squared)

