def create_histogram2d(nx, ny, xrange, yrange):
    if not isinstance(nx, int) or nx <= 0:
        raise ValueError("nx must be a positive integer")
    if not isinstance(ny, int) or ny <= 0:
        raise ValueError("ny must be a positive integer")
    if not isinstance(xrange, list) or not isinstance(yrange, list):
        raise TypeError("xrange and yrange must be lists")
    if len(xrange) != nx + 1 or len(yrange) != ny + 1:
        raise ValueError("xrange and yrange must have nx+1 and ny+1 elements")
    for i in range(1, len(xrange)):
        if xrange[i] <= xrange[i-1]:
            raise ValueError("xrange must be strictly increasing")
    for i in range(1, len(yrange)):
        if yrange[i] <= yrange[i-1]:
            raise ValueError("yrange must be strictly increasing")
    x_array = (ctypes.c_double * len(xrange))(*xrange)
    y_array = (ctypes.c_double * len(yrange))(*yrange)
    result = gsl.create_histogram2d(nx, ny, x_array, y_array)
    if not result:
        raise RuntimeError("Failed to create histogram")
    return result

